import os
from flask import Flask, request
app = Flask(__name__)


ROOT = "/srv/attachments"


@app.route("/attachment")
def attachment():
    # os.path.join normalises the path, so "../" sequences are neutralised here
    path = os.path.join(ROOT, request.args.get("file", ""))
    with open(path, "rb") as f:
        return f.read()
